func TestDecodeMessage(t *testing.T) {
	//{"type":"evm-incremental","chain":"base","data":{"blockNumber":40344842,"block":{"hash":"0x16a39d4adfe66ea422ce120ab63e5af50c38d22ece50edb163fa0822339dc1be","parentHash":"0x4521897e6bf51a7f9699cb5ba1b3e8e1b4f9732aa8bce9ec95c8360eb10fa366","sha3Uncles":"0x1dcc4de8dec75d7aab85b567b6ccd41ad312451b948a7413f0a142fd40d49347","miner":"0x4200000000000000000000000000000000000011","stateRoot":"0x5c4fa27b72420bbdd7f104e8daa90add55e27de34e7c1d0a9343dbe6c2cc5386","transactionsRoot":"0xecd761f3fb9e19d8a655d18d221b0738d635a25cbc14934483be2333d56caa79","receiptsRoot":"0xb6dcf37b06bae1703fe03ede5154e91c24d399ea7febded23b569cc764547d23","logsBloom":"","difficulty":"0x0","number":"0x2679d0a","gasLimit":"0x165a0bc0","gasUsed":"0x3f536e2","timestamp":"0x695996f7","extraData":"0x010000003200000006000000000007a120","mixHash":"0xd9cd5991329d600239667efc35d3949dce46d19043ebf52bdae57d9cb7eb0b6d","nonce":"0x0000000000000000","baseFeePerGas":"0x24343b","withdrawalsRoot":"0x9fe94a759e5c36931cf4bf1df55d2254587f21230399e6b115ce9d2ed210c9c4","blobGasUsed":"0x124c2c7","excessBlobGas":"0x0","parentBeaconBlockRoot":"0xd9f8129b1d2ff07278723888362db8e03e13cbb48344939b0cb9194726e010f7","requestsHash":"0xe3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855","size":"0x28696","uncles":[],"transactions":[],"withdrawals":[]},"receipts":[],"traceBlock":[]},"timestamp":0,"block_number":40344842,"delay_flag":true}
	data := ""
	decodeBytes, _ := base64.StdEncoding.DecodeString(data)
	output, _ := snappy.Decode(nil, decodeBytes)
	// os.WriteFile("test.log", output, 0644)
	var msg Message
	var evmRes EvmResult
	var evmDb EvmDataBlock
	err := json.Unmarshal(output, &msg)
	if err != nil {
		t.Fatal(err)
	}
	err = json.Unmarshal(msg.Data, &evmRes)
	if err != nil {
		t.Fatal(err)
	}
	err = json.Unmarshal(evmRes.Block, &evmDb)
	if err != nil {
		t.Fatal(err)
	}

	ts, err := strconv.ParseInt(evmDb.Timestamp, 0, 64)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("time: %d", ts)

	// tsUtc, err := service.ConverTsToTimeZone(ts, service.Shanghai)
	// if err == nil {
	// 	t.Logf("UTC : %d", tsUtc)
	// }
}
